import contextlib
import io
import pathlib
import subprocess
import sys
import unittest

from textkit.cli import main
from textkit.near import closest, levenshtein

ROOT = pathlib.Path(__file__).resolve().parent.parent


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class LevenshteinTest(unittest.TestCase):
    def test_examples(self):
        self.assertEqual(levenshtein("kitten", "sitting"), 3)
        self.assertEqual(levenshtein("helo", "hello"), 1)
        self.assertEqual(levenshtein("", "abc"), 3)
        self.assertEqual(levenshtein("abc", ""), 3)
        self.assertEqual(levenshtein("", ""), 0)

    def test_symmetric(self):
        self.assertEqual(levenshtein("flaw", "lawn"), levenshtein("lawn", "flaw"))


class ClosestTest(unittest.TestCase):
    def test_picks_nearest(self):
        self.assertEqual(closest("helo", ["hello", "help"]), "hello")

    def test_ties_go_to_first(self):
        self.assertEqual(closest("cat", ["cot", "cab"]), "cot")
        self.assertEqual(closest("cat", ["cab", "cot"]), "cab")

    def test_within_max_distance_is_inclusive(self):
        self.assertEqual(closest("abc", ["abcde"], max_distance=2), "abcde")

    def test_beyond_max_distance_is_none(self):
        self.assertIsNone(closest("abc", ["abcde"], max_distance=1))
        self.assertIsNone(closest("zzzz", ["hello"]))

    def test_empty_candidates_is_none(self):
        self.assertIsNone(closest("hello", []))

    def test_default_max_distance_is_two(self):
        self.assertEqual(closest("abc", ["axy"]), "axy")
        self.assertIsNone(closest("abc", ["wxyz"]))

    def test_negative_max_distance_raises(self):
        with self.assertRaises(ValueError):
            closest("helo", ["hello"], max_distance=-1)
        with self.assertRaises(ValueError):
            closest("helo", [], max_distance=-1)


class NearCommandTest(unittest.TestCase):
    def test_prints_match(self):
        self.assertEqual(run("near", "helo", "hello", "help"), (0, "hello\n", ""))

    def test_no_match_exits_1_with_message_on_stderr(self):
        self.assertEqual(run("near", "zzzz", "hello"), (1, "", "no match\n"))

    def test_max_option(self):
        self.assertEqual(run("near", "helo", "hello", "--max", "0"), (1, "", "no match\n"))
        self.assertEqual(run("near", "helo", "hello", "--max", "1"), (0, "hello\n", ""))

    def test_negative_max_exits_2_with_error(self):
        code, out, err = run("near", "helo", "hello", "--max", "-1")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error:"))

    def test_json_output(self):
        code, out, _ = run("--json", "near", "helo", "hello")
        self.assertEqual(code, 0)
        self.assertIn('"command": "near"', out)
        self.assertIn('"output": ["hello"]', out)

    def test_real_process_exit_statuses(self):
        def proc(*args):
            return subprocess.run(
                [sys.executable, "-m", "textkit", *args],
                cwd=ROOT, capture_output=True, text=True,
            )

        p = proc("near", "helo", "hello", "help")
        self.assertEqual((p.returncode, p.stdout), (0, "hello\n"))

        p = proc("near", "zzzz", "hello")
        self.assertEqual((p.returncode, p.stderr), (1, "no match\n"))

        p = proc("near", "helo", "hello", "--max", "-1")
        self.assertEqual(p.returncode, 2)
        self.assertTrue(p.stderr.startswith("error:"))


if __name__ == "__main__":
    unittest.main()

